-- Admin-editable study-plan maps (see StudyMapService). Each publish adds a version;
-- the map shown is the highest version for its plan.
-- Version 1 of each plan is the 2022 map that used to be hard-coded in the client
-- (generated from client/src/components/layout/{node,edge}/...; same nodes, positions,
-- colours and arrows; arrows to boxes that don't exist were dropped, they were never drawn).
-- Removing a course from a map later never deletes the course itself.

CREATE TABLE study_maps (
    id         bigint GENERATED BY DEFAULT AS IDENTITY,
    plan       varchar(10) NOT NULL,
    version    integer NOT NULL,
    content    text NOT NULL,
    created_by bigint,
    created_at timestamp(6),
    CONSTRAINT study_maps_pkey PRIMARY KEY (id),
    CONSTRAINT uk_study_maps_plan_version UNIQUE (plan, version),
    CONSTRAINT fk_study_maps_created_by FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
);

